mapper.select:
SELECT




        op.incident_id = #{incidentId,typeHandler=com.surimap.config.mybatis.UuidTypeHandler}


        AND ds.operational_period_id = #{opId,typeHandler=com.surimap.config.mybatis.UuidTypeHandler}


        AND COALESCE(started_event.actor_police_phone_id, ds.police_phone_id) = #{policePhoneId,typeHandler=com.surimap.config.mybatis.UuidTypeHandler}


        AND sp.account_id = #{accountId,typeHandler=com.surimap.config.mybatis.UuidTypeHandler}


ORDER BY sp.updated_at DESC, sp.id ASC
